        Return the README details from the README.md for documentation
    Args:
        readme_file_location (String): Project README file
    Return:
        requirement_files (List of Strings): Requirement Files
    """
def get_readme(readme_file_location: Any = "./README.md") -> object {
    readme_data = "Description Not Found";
    try {
        with open(readme_file_location, "r") as readme_file_object {
            readme_data = readme_file_object.read();
        }
    } except Exception as err {
        print(f"Failed to Get README.md Data from {readme_file_location}: {err}");
    }
    return readme_data;
}

""" convert an indent of tab to spaces
    ex.) python main.py -tab2sp 4
        --> an indenct of tab to 4 spaces
    """
def tab2sp(line: Any, spaces: Any) -> object {
    cnt = 0;
    tabs = "\t";
    while line.startswith(tabs) {
        cnt += 1;
        tabs += "\t";
    }
    return line.replace("\t", spaces, cnt);
}

"""Function will convert bool to int and int to bool"""
def convert_int_bool(t_input: Any) -> object {
    if isinstance(t_input, bool) {
        if t_input {
            return 1;
        }
        return 0;
    } elif isinstance(t_input, str) {
        try {
            t_input = int(t_input);
            if (t_input == 0) {
                return False;
            } else {
                return True;
            }
        } except ValueError {
            return None;
        }
    } elif isinstance(t_input, int) {
        if (t_input == 0) {
            return False;
        } else {
            return True;
        }
    }
    return None;
}

