"""Extract a section of a certain length from a string.

    Args:
        string (str): The string to extract from.
        start (int): How many chars to move forward.
        len_ (int): The amount of chars to extract.

    Returns:
        str: The extracted string.
    """
def extract(string: str, start: int, len_: int) -> str {
    start -= 1;
    return string[start:(start + len_)].strip();
}

""" Splits a string but allows escape characters """
def _split_escape_string(
    input: Any, keep_escape: Any = True, splitchar: Any = ',', escapechar: Any = '\\'
) -> object {
    results = [];
    string = "";
    escaped = False;
    for c in input {
        if (not escaped and (c == escapechar)) {
            escaped = True;
            if keep_escape {
                string += c;
            }
        } elif (not escaped and (c == splitchar)) {
            results.append(string);
            string = "";
        } else {
            string += c;
            escaped = False;
        }
    }
    results.append(string);
    return results;
}

